-- 공개 메뉴 「아추!」 넣기 · 「인기글」 숨기기(docs/features/achu-page-contract.md, 사용자 2026-11-19) — 이미 설치된 DB 에 새 설치(설치 프리셋 irobit.structure.json · neutral.json)와 같은 메뉴를 만든다.
--
-- 이미 설치된 DB 에서만(installation.status = COMPLETED 이고 board_preset_applied_at 이 있는 곳) — 빈 DB 는 설치 프리셋이 만든다. 다시 돌아도 그대로다(조건마다 「없을 때만」).
-- ① 공개 메뉴 main 에 BUILTIN ACHU 항목이 하나도 없을 때만 최상위에 넣는다 — 「인기글」(BUILTIN POPULAR) 바로 다음(없으면 「홈」 다음, 그것도 없으면 최상위 끝), 뒤 형제 차례를 1 씩 민다.
--    이름은 내장 이름(label NULL — 「아추!」/「Achu!」), 이름 모양 LOGO(로고 글꼴 그림 — 설치 프리셋과 같은 패스), 보임 · 모두 · 모바일 탭 아님.
-- ② 최상위 「인기글」(BUILTIN POPULAR)을 숨긴다(visible = false — 항목은 남겨 메뉴 관리에서 다시 켤 수 있다). 하단 탭·/popular 화면은 그대로다.
-- 바꾼 것이 있으면 main 의 트리 버전을 1 올린다(관리자 저장의 MENU_VERSION_CONFLICT — 열려 있던 편집 화면이 옛 트리로 덮어쓰지 않게, V99·V211 과 같다).
-- ID 는 그 시각의 Snowflake(EPOCH 2026-01-01 UTC, 노드 1023 — 마이그레이션용 노드, V43·V99·V211 과 같은 방식) + 순번(같은 표에 이미 있으면 건너뛴다).
-- 서버는 이 마이그레이션 뒤에 뜨므로 메뉴 캐시는 비어 있다(따로 비울 것 없음).
DO $achu$
DECLARE
    v_base    bigint := ((greatest(0, (extract(epoch FROM clock_timestamp()) * 1000)::bigint - 1767225600000)) << 22) | (1023::bigint << 12);
    v_seq     int := 0;
    v_id      bigint;
    v_order   int;
    v_anchor  int;
    v_changed boolean := false;
    v_hidden  int;
BEGIN
    PERFORM 1 FROM installation i WHERE i.id = 1 AND i.status = 'COMPLETED' AND i.board_preset_applied_at IS NOT NULL;
    IF NOT FOUND THEN
        RETURN; -- 설치 전·설치 프리셋을 아직 적용하지 않은 DB — 새 설치는 프리셋 적용이 만든다
    END IF;
    IF NOT EXISTS (SELECT 1 FROM menu_sets WHERE set_key = 'main') THEN
        RETURN;
    END IF;

    -- ── ① 아추! ────────────────────────────────────────────────────────────────
    IF NOT EXISTS (SELECT 1 FROM menu_nodes n WHERE n.set_key = 'main' AND n.kind = 'ITEM' AND n.target_type = 'BUILTIN' AND n.target_key = 'ACHU') THEN
        SELECT n.sort_order INTO v_anchor
          FROM menu_nodes n
         WHERE n.set_key = 'main' AND n.parent_id IS NULL AND n.kind = 'ITEM' AND n.target_type = 'BUILTIN' AND n.target_key = 'POPULAR'
         ORDER BY n.sort_order, n.id
         LIMIT 1;
        IF NOT FOUND THEN
            SELECT n.sort_order INTO v_anchor
              FROM menu_nodes n
             WHERE n.set_key = 'main' AND n.parent_id IS NULL AND n.kind = 'ITEM' AND n.target_type = 'BUILTIN' AND n.target_key = 'HOME'
             ORDER BY n.sort_order, n.id
             LIMIT 1;
        END IF;
        IF v_anchor IS NOT NULL THEN
            UPDATE menu_nodes SET sort_order = sort_order + 1
             WHERE set_key = 'main' AND parent_id IS NULL AND sort_order > v_anchor;
            v_order := v_anchor + 1;
        ELSE
            SELECT coalesce(max(n.sort_order) + 1, 0) INTO v_order FROM menu_nodes n WHERE n.set_key = 'main' AND n.parent_id IS NULL;
        END IF;
        LOOP
            v_seq := v_seq + 1;
            v_id := v_base | v_seq;
            EXIT WHEN NOT EXISTS (SELECT 1 FROM menu_nodes WHERE id = v_id);
        END LOOP;
        INSERT INTO menu_nodes (id, set_key, parent_id, kind, sort_order, visible, audience, target_type, target_key, mobile_tab, divider, shortcut, bold, name_style, name_art)
