    -- ── ② 인기글 숨기기 ────────────────────────────────────────────────────────
    UPDATE menu_nodes SET visible = false
     WHERE set_key = 'main' AND parent_id IS NULL AND kind = 'ITEM' AND target_type = 'BUILTIN' AND target_key = 'POPULAR' AND visible;
    GET DIAGNOSTICS v_hidden = ROW_COUNT;
    IF v_hidden > 0 THEN
